'use server'

import { revalidatePath } from 'next/cache'
import { getNotificationPreference, setNotificationPreference } from './lib/notifications'

export async function toggleNotificationPreference() {
  const current = getNotificationPreference()
  setNotificationPreference(!current)

  // Re-render the current route on the server and push fresh data to the
  // client, without navigating away from the page.
  revalidatePath('/')
}

