args.content:
import { toggleNotificationPreference } from './actions'
import { getNotificationPreference } from './lib/notifications'

export default function Home() {
  const notificationsEnabled = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {notificationsEnabled ? 'ON' : 'OFF'}.</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

